        ['id' => 83101, 'event_id' => 831, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>What does the evidence say?</h3><p>The sick plants have damaged cells, but you found <strong>no fungus and no bacteria</strong> in any sample.</p><p>What is the best conclusion?</p>', 'call_to_actions' => [['text' => 'The plants caught an infection that spreads from plant to plant', 'action' => ['type' => 'run_event', 'target_event_id' => 832]], ['text' => 'Something in their surroundings is damaging them', 'action' => ['type' => 'run_event', 'target_event_id' => 833]], ['text' => 'The microscope must be broken', 'action' => ['type' => 'run_event', 'target_event_id' => 834]]], 'dismissible' => false]],
        ['id' => 83201, 'event_id' => 832, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_cells', 'operator' => 'set', 'operand' => 'a']],
