        ['id' => 83303, 'event_id' => 833, 'type' => 'infobox', 'sequence' => 4, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Correct!</h3><p>Yes. With no microbes present, an infection is unlikely. The damage is more likely caused by something in the <strong>environment</strong>, such as the water the plants are growing in.</p>']],
        ['id' => 83401, 'event_id' => 834, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_cells', 'operator' => 'set', 'operand' => 'c']],
