        ['id' => 84303, 'event_id' => 843, 'type' => 'infobox', 'sequence' => 4, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Correct!</h3><p>Right. A <strong>base</strong> cancels out an acid. Scientists call this <strong>neutralising</strong>. Now test your prediction.</p>']],
        ['id' => 84401, 'event_id' => 844, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_base', 'operator' => 'set', 'operand' => 'c']],
        ['id' => 84402, 'event_id' => 844, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Not quite</h3><p>Salt dissolves but does not change the pH. A <strong>base</strong>, such as baking soda, cancels out an acid. Try it and watch the number.</p>']],
        ['id' => 84501, 'event_id' => 845, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Mixing bench</h3><p><img src="{{media:40}}" width="520" alt=""></p><p>The beaker of gully water now reads <strong>pH {{beaker_ph}}</strong>.</p><p>Add one drop at a time and watch what happens to the number.</p>', 'call_to_actions' => [['text' => 'Add a drop of baking soda solution (a base)', 'action' => ['type' => 'variable', 'name' => 'beaker_ph', 'operator' => '+', 'operand' => 1], 'conditions' => [['variable' => 'beaker_ph', 'operator' => '<', 'operand' => 14]]], ['text' => 'Add a drop of lemon juice (an acid)', 'action' => ['type' => 'variable', 'name' => 'beaker_ph', 'operator' => '-', 'operand' => 1], 'conditions' => [['variable' => 'beaker_ph', 'operator' => '>', 'operand' => 0]]], ['text' => 'Step away', 'action' => ['type' => 'variable', 'name' => 'beaker_done', 'operator' => 'set', 'operand' => 1]]], 'dismissible' => false]],
        ['id' => 84502, 'event_id' => 845, 'type' => 'infobox', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Neutral!</h3><p>The beaker reads <strong>pH 7</strong>. Each drop of base cancelled out some of the acid. If the leak were stopped, the stream could recover in the same way.</p>']],
        ['id' => 84503, 'event_id' => 845, 'type' => 'variable', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'neutralised', 'operator' => 'set', 'operand' => 1]],
        ['id' => 84590, 'event_id' => 845, 'type' => 'award', 'sequence' => 4, 'blocking' => false, 'media_id' => null, 'params' => ['note' => 'Water made neutral', 'stars' => 10, 'xp' => 30]],
        ['id' => 84504, 'event_id' => 845, 'type' => 'repeat', 'sequence' => 5, 'blocking' => true, 'media_id' => null, 'params' => []],
        ['id' => 86101, 'event_id' => 861, 'type' => 'infobox', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Your report</h3><p>Look at your notebook. Where do the sick plants grow, and what is different about the water there?</p><p><strong>What is the most likely source of the contamination?</strong></p>', 'call_to_actions' => [['text' => 'A plant disease spreading along the stream', 'action' => ['type' => 'run_event', 'target_event_id' => 862]], ['text' => 'Acid leaking from the old lander\'s power cell into the stream', 'action' => ['type' => 'run_event', 'target_event_id' => 863]], ['text' => 'Too little sunlight in the gully and the marsh', 'action' => ['type' => 'run_event', 'target_event_id' => 864]]]]],
        ['id' => 86201, 'event_id' => 862, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_source', 'operator' => 'set', 'operand' => 'a']],
        ['id' => 86202, 'event_id' => 862, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'source_tries', 'operator' => '+', 'operand' => 1]],
        ['id' => 86203, 'event_id' => 862, 'type' => 'infobox', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Check the evidence</h3><p>A disease would be caused by microbes, and the microscope showed <strong>none</strong> in any sample. Look again at the pH column in your notebook: what changes between the meadow and the gully?</p>']],
        ['id' => 86301, 'event_id' => 863, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_source', 'operator' => 'set', 'operand' => 'b']],
        ['id' => 86302, 'event_id' => 863, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'science_score', 'operator' => '+', 'operand' => 1]],
        ['id' => 86303, 'event_id' => 863, 'type' => 'variable', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'quest_solved', 'operator' => 'set', 'operand' => 1]],
        ['id' => 86390, 'event_id' => 863, 'type' => 'award', 'sequence' => 4, 'blocking' => false, 'media_id' => null, 'params' => ['note' => 'Mission complete', 'stars' => 25, 'xp' => 100]],
        ['id' => 86304, 'event_id' => 863, 'type' => 'infobox', 'sequence' => 5, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Mystery solved</h3><p>The evidence fits together:</p><ul><li>Upstream of the lander the water is neutral and the plants are healthy.</li><li>Just below the lander the water is strongly acidic and the plants are worst.</li><li>Further downstream the acid is weaker, and the plants are sick but less so.</li><li>No microbes were found, so it is not an infection.</li></ul><p>The cracked power cell is leaking acid into the stream. A repair crew is on its way.</p><p><strong>Science score: {{science_score}} out of 5.</strong></p>']],
        ['id' => 86401, 'event_id' => 864, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'q_source', 'operator' => 'set', 'operand' => 'c']],
        ['id' => 86402, 'event_id' => 864, 'type' => 'variable', 'sequence' => 2, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'source_tries', 'operator' => '+', 'operand' => 1]],
        ['id' => 86403, 'event_id' => 864, 'type' => 'infobox', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Check the evidence</h3><p>All three sites are out in the open under the same sky, so sunlight is the same for each. A good explanation has to account for what is <em>different</em> between the healthy site and the sick ones. What did the pH tests show?</p>']],

