        ['id' => 116001, 'event_id' => 1160, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['text' => 'The seed vault stays shut. The bay’s three critters do not know you yet: say hello to each of them ({{critters_met}}/3).', 'alignment' => 'bottom center', 'text_font_size' => 26, 'duration' => 4500]],
        ['id' => 116101, 'event_id' => 1161, 'type' => 'variable', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['name' => 'vault_opened', 'operator' => 'set', 'operand' => 1]],
        ['id' => 116102, 'event_id' => 1161, 'type' => 'award', 'sequence' => 2, 'blocking' => false, 'media_id' => null, 'params' => ['stars' => 5, 'xp' => 15, 'note' => 'Friend of the bay']],
        ['id' => 116103, 'event_id' => 1161, 'type' => 'infobox', 'sequence' => 3, 'blocking' => true, 'media_id' => null, 'params' => ['content' => '<h3>Seed vault</h3><p>The critters chirp, and the vault slides open for you. Inside are seeds from every world the ship has visited, kept cold and dry until they are needed.</p><p>Each explorer has to make friends with the critters themselves: your friend’s greeting does not open the vault for you.</p>']],

        // scene 12
        ['id' => 120101, 'event_id' => 1201, 'type' => 'text_overlay', 'sequence' => 1, 'blocking' => true, 'media_id' => null, 'params' => ['text' => 'Engine room', 'alignment' => 'top center', 'text_font_size' => 30, 'duration' => 2500]],
